import{z as l,x as A,o as e,c as s,q as i,j as n,D as E,d as o,s as r,S as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"接触孔与线端成像","description":"","frontmatter":{"title":"接触孔与线端成像","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/2d-imaging-contacts-lineend.md","filePath":"litho/2d-imaging-contacts-lineend.md","lastUpdated":1791063341000}'),d={name:"litho/2d-imaging-contacts-lineend.md"};function h(p,a,c,m,_,D){const t=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=i('<h1 id="接触孔与线端成像" tabindex="-1">接触孔与线端成像 <a class="header-anchor" href="#接触孔与线端成像" aria-label="Permalink to &quot;接触孔与线端成像&quot;">​</a></h1><div class="epigraph"><p>一维骨架把线栅收成几根齿；孔和线端把频谱铺成二维斑，光瞳切的是面积，核在两个方向上同时卷积。</p><footer>—— Goodman 的二维傅里叶对；孔与线端的光刻读法见 Mack</footer></div><p><a href="/litho/focus-tilt-compensation">上一课</a>结束了传递函数课序。缺口是：骨架一直可以在一维线上讲完，<strong>接触孔与线端</strong>却必须用二维卷积。主干已有<a href="/litho/contact-hole-patterning">接触孔图形化</a>与<a href="/litho/line-end-shortening">线端缩短</a>的产线侧；本课只把它们接到 PSF / TCC，不重写孔层流程与锤头 OPC。禁戒节距留给<a href="/litho/forbidden-pitch">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线栅的 \\(T\\) 是梳；圆孔或方孔的 \\(T\\) 是 jinc 或 sinc 的二维斑，能量散在面积上。光瞳切掉斑的外圈，像面核把孔糊成圆丘，对比和 NILS 通常弱于同样 \\(k_1\\) 叙事下的密线——因为两个方向都要过截止。线端是矩形的突然终止：纵向也出现锐边，二维核把端面收成圆帽，阈值轮廓内缩。</p><p><span class="marginnote">术语翻译：jinc 就是把一维的 sinc「转」成圆对称的版本，可以想象成圆形孔自己的衍射指纹。sinc 把能量收成几根梳齿，jinc 却摊成一圈圈同心环——这正是孔比线更费光瞳面积的原因。</span></p><p>缺口不是再定义 Airy，而是：后课二维图形（角、EPE）默认已经会用「面积频谱 × 核」来读孔和端，而不是把孔当成「短一点的线」。</p><h3 id="照明各向同性" tabindex="-1">照明各向同性 <a class="header-anchor" href="#照明各向同性" aria-label="Permalink to &quot;照明各向同性&quot;">​</a></h3><p>强偶极抬一维节距，同时把孔拉成长圆、把线端的横纵糊不对称。孔阵列常用常规或弱四极，正是让二维斑在光瞳里比较圆。本课不选产品照明；只要求报孔 CD 与 LES 时声明 \\(S\\) 的对称性。矢量浸没下两向不能同时 TE，孔再付一笔<a href="/litho/immersion-vector-imaging">上一课序</a>的税。</p><p><span class="marginnote">方孔的角在掩模上是直角，空中像在光学直径内已经圆。计量若报「孔圆度」，先问是光学核还是刻蚀。主干孔课管工艺窗与随机缺失；本课管成像核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计算：在同一套 SOCS 核上放有限长线或孔阵列，切阈值等高线。相对无限长线的中段，端面内缩量即光学 LES；相对掩模方孔，像面等强度线变圆即光学圆化。邻孔进入光学直径后，交叉项按 Hopkins 双线性进来——孤立孔与密阵列不是同一只有效核。</p><p>采样：二维 Nyquist 两个方向都要满足，孔的旁瓣折叠会假造「邻孔桥连」。网格规则沿用<a href="/litho/sampling-theorem-imaging">采样课</a>。</p>',13)),(e(),n(B,null,{default:E(()=>[r(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINE%5B%22%E4%B8%80%E7%BB%B4%E6%A2%B3%E7%8A%B6%E8%B0%B1%22%5D%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%E5%88%87%E9%BD%BF%22%5D%0A%20%20HOLE%5B%22%E4%BA%8C%E7%BB%B4%E6%96%91%E8%B0%B1%22%5D%20--%3E%20PUP%0A%20%20END%5B%22%E7%BA%BF%E7%AB%AF%E9%94%90%E7%BB%88%E6%AD%A2%22%5D%20--%3E%20PUP%0A%20%20PUP%20--%3E%20PSF2%5B%22%E4%BA%8C%E7%BB%B4%20PSF%20%E5%8D%B7%E7%A7%AF%22%5D%0A%20%20PSF2%20--%3E%20CONT%5B%22%E5%AD%94%EF%BC%9A%E5%9C%86%E4%B8%98%20%2F%20%E4%BD%8E%20NILS%22%5D%0A%20%20PSF2%20--%3E%20LES%5B%22%E7%BA%BF%E7%AB%AF%EF%BC%9A%E5%9C%86%E5%B8%BD%E5%86%85%E7%BC%A9%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="与主干课的分工" tabindex="-1">与主干课的分工 <a class="header-anchor" href="#与主干课的分工" aria-label="Permalink to &quot;与主干课的分工&quot;">​</a></h3><p>主干孔课回答层怎么选照明、相移、过刻；主干 LES 课回答怎么量缩短、怎么意识到中段 CD 看不见端。本课只提供前向：为什么二维一定更糊。修版（锤头、衬线、孔偏置）仍属 OPC，这里不出场。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>卷积把物体的每个凸起与 \\(h\\) 做相关。孔的直径若接近核宽度，峰值掉、边缓，剂量一点就穿或封。线端相当于半平面终止，核的一半悬空，等强度线回缩约核半径量级，随焦点变本加厉——因为离焦让核更胖。部分相干交叉项让对面线端、邻孔参与这场回缩，所以 LES–间隙曲线不是常数。</p><p><span class="marginnote">核宽度的直觉数字：NA=1.35、\\(\\lambda=193\\) nm 时 Airy 主瓣半径约 \\(0.61\\lambda/\\mathrm{NA}\\approx 87\\) nm。所谓「回缩约核半径量级」，就是几十纳米这一档——比 1 nm 级的刻蚀涨落显眼得多，所以光学 LES 必须先单独算清。</span></p><p><span class="marginnote">初学者容易把线端缩短全归给胶收缩或刻蚀负载；实际上光学 LES 在曝光那一瞬就由二维核决定了。剂量或焦点一变它先动，工艺侧只能「再修」，不能把它归零。</span></p>',6)),(e(),n(B,null,{default:E(()=>[r(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E4%BA%8C%E7%BB%B4%E6%A0%B8%20h%22%5D%20--%3E%7C%E7%A6%BB%E7%84%A6%7C%20FAT%5B%22%E6%A0%B8%E5%8F%98%E5%AE%BD%22%5D%0A%20%20END2%5B%22%E7%BA%BF%E7%AB%AF%EF%BC%9A%E5%8D%8A%E5%B9%B3%E9%9D%A2%E9%94%90%E7%BB%88%E6%AD%A2%22%5D%20--%3E%20PULL%5B%22%E7%AD%89%E5%BC%BA%E5%BA%A6%E7%BA%BF%E5%9B%9E%E7%BC%A9%22%5D%0A%20%20FAT%20--%3E%20PULL%0A%20%20PULL%20--%3E%20LESG%5B%22LES%20%E9%9A%8F%E7%84%A6%E7%82%B9%E5%A2%9E%E9%95%BF%22%5D%0A%20%20NB%5B%22%E9%82%BB%E5%AD%94%2F%E5%AF%B9%E9%9D%A2%E7%BA%BF%E7%AB%AF%E8%BF%9B%E5%85%A5%E5%85%89%E5%AD%A6%E7%9B%B4%E5%BE%84%22%5D%20--%3E%20X%5B%22Hopkins%20%E4%BA%A4%E5%8F%89%E9%A1%B9%22%5D%0A%20%20X%20--%3E%20LESG%0A%20%20X%20--%3E%20BR%5B%22%E9%82%BB%E5%AD%94%E5%81%87%E6%A1%A5%E8%BF%9E%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>胶扩散与刻蚀再收一截，光学项必须先分开：改照明或改对面间隙，光学 LES 先动。EUV 缺孔是计数统计，不是 Airy 太胖的同义词。禁止把未公开的某层「孔 NILS 门槛」当普遍常数。也不要把 Sparrow 两点距直接当孔阵列节距规则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>孔与线端是二维频谱被光瞳切面积，不是短线栅。</li><li>光学 LES 与孔圆化来自同一只二维核。</li><li>照明对称性决定孔椭圆和端头各向异性。</li><li>邻域交叉项用 TCC，不把孤立核当密阵列。</li><li>下一课：一维 through-pitch 上的禁戒节距。</li><li>出处：Goodman；Mack；Hopkins (1953)。</li></ul>',4))])}const f=l(d,[["render",h]]);export{P as __pageData,f as default};
